package com.hrcoresystem.hrcore_api.common.config;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantHrOperationalGuard; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.servlet.HandlerInterceptor;
@Component public class TenantHrReadinessInterceptor implements HandlerInterceptor { private final TenantHrOperationalGuard guard; public TenantHrReadinessInterceptor(TenantHrOperationalGuard g){guard=g;} @Override public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler){String m=req.getMethod(); if((m.equals("POST")||m.equals("PUT")||m.equals("PATCH")||m.equals("DELETE")) && (req.getRequestURI().equals("/api/shifts")||req.getRequestURI().startsWith("/api/shifts/")||req.getRequestURI().equals("/api/attendance")||req.getRequestURI().startsWith("/api/attendance/"))) guard.assertConfigured(); return true;} }
